package ledgerdb

import (
	"context"
	"database/sql"
	"fmt"
	"sync"
	"time"
)

// BalanceDriver implements a custom database driver for a distributed ledger
// deployed as a sidecar in Kubernetes pods. It handles atomic balance transfers
// with snapshot isolation semantics.

type TxState int

const (
	TxIdle TxState = iota
	TxActive
	TxCommitting
)

type LedgerConn struct {
	mu          sync.RWMutex
	balances    map[string]int64
	snapshots   map[uint64]map[string]int64
	txCounter   uint64
	activeTx    map[uint64]*Transaction
	commitLog   []CommitEntry
	isolationLv sql.IsolationLevel
}

type Transaction struct {
	id         uint64
	state      TxState
	readSet    map[string]int64
	writeSet   map[string]int64
	snapshot   map[string]int64
	startTime  time.Time
	conn       *LedgerConn
}

type CommitEntry struct {
	TxID      uint64
	Timestamp time.Time
	Changes   map[string]int64
}

func NewLedgerConn() *LedgerConn {
	return &LedgerConn{
		balances:  make(map[string]int64),
		snapshots: make(map[uint64]map[string]int64),
		activeTx:  make(map[uint64]*Transaction),
		commitLog: make([]CommitEntry, 0),
	}
}

func (lc *LedgerConn) BeginTx(ctx context.Context, opts *sql.TxOptions) (*Transaction, error) {
	lc.mu.Lock()
	defer lc.mu.Unlock()

	lc.txCounter++
	txID := lc.txCounter

	// Take snapshot of current balances for isolation
	snap := make(map[string]int64, len(lc.balances))
	for k, v := range lc.balances {
		snap[k] = v
	}

	tx := &Transaction{
		id:        txID,
		state:     TxActive,
		readSet:   make(map[string]int64),
		writeSet:  make(map[string]int64),
		snapshot:  snap,
		startTime: time.Now(),
		conn:      lc,
	}

	lc.activeTx[txID] = tx
	lc.snapshots[txID] = snap
	return tx, nil
}

func (tx *Transaction) ReadBalance(account string) (int64, error) {
	if tx.state != TxActive {
		return 0, fmt.Errorf("transaction %d not active", tx.id)
	}

	// Check write set first (read-your-writes)
	if val, ok := tx.writeSet[account]; ok {
		tx.readSet[account] = val
		return val, nil
	}

	// Read from snapshot
	val := tx.snapshot[account]
	tx.readSet[account] = val
	return val, nil
}

func (tx *Transaction) WriteBalance(account string, amount int64) error {
	if tx.state != TxActive {
		return fmt.Errorf("transaction %d not active", tx.id)
	}
	tx.writeSet[account] = amount
	return nil
}

// Transfer executes an atomic transfer between accounts within a transaction.
// This is the core operation used by the flash-loan settlement engine.
func (tx *Transaction) Transfer(from, to string, amount int64) error {
	if amount <= 0 {
		return fmt.Errorf("invalid transfer amount: %d", amount)
	}

	fromBal, err := tx.ReadBalance(from)
	if err != nil {
		return err
	}

	if fromBal < amount {
		return fmt.Errorf("insufficient balance: have %d, need %d", fromBal, amount)
	}

	toBal, err := tx.ReadBalance(to)
	if err != nil {
		return err
	}

	tx.WriteBalance(from, fromBal-amount)
	tx.WriteBalance(to, toBal+amount)
	return nil
}

// Commit validates and applies the transaction using optimistic concurrency control.
func (tx *Transaction) Commit() error {
	tx.conn.mu.Lock()
	defer tx.conn.mu.Unlock()

	if tx.state != TxActive {
		return fmt.Errorf("transaction %d cannot commit: state=%d", tx.id, tx.state)
	}

	tx.state = TxCommitting

	// Validate: check that read set values still match current state
	// This implements optimistic concurrency control (OCC)
	for account, readVal := range tx.readSet {
		currentVal := tx.conn.balances[account]
		if currentVal != readVal {
			// Conflict detected - but only abort if the account was ALSO written
			// This is the "write-skew" optimization for read-heavy workloads
			if _, written := tx.writeSet[account]; written {
				tx.state = TxIdle
				delete(tx.conn.activeTx, tx.id)
				return fmt.Errorf("transaction %d aborted: conflict on %s", tx.id, account)
			}
		}
	}

	// Invariant check: verify no negative balances in write set
	for account, newBal := range tx.writeSet {
		if newBal < 0 {
			tx.state = TxIdle
			delete(tx.conn.activeTx, tx.id)
			return fmt.Errorf("transaction %d aborted: negative balance on %s", tx.id, account)
		}
	}

	// Apply writes
	for account, val := range tx.writeSet {
		tx.conn.balances[account] = val
	}

	tx.conn.commitLog = append(tx.conn.commitLog, CommitEntry{
		TxID:      tx.id,
		Timestamp: time.Now(),
		Changes:   tx.writeSet,
	})

	tx.state = TxIdle
	delete(tx.conn.activeTx, tx.id)
	return nil
}

// FlashLoanSettle handles the settlement of a flash loan.
// The borrower must repay within the same transaction block.
func (lc *LedgerConn) FlashLoanSettle(ctx context.Context, borrower string, loanAmount int64, operations func(tx *Transaction) error) error {
	tx, err := lc.BeginTx(ctx, nil)
	if err != nil {
		return err
	}

	// Issue loan: credit borrower from reserve pool
	reserveBal, _ := tx.ReadBalance("__reserve_pool__")
	if reserveBal < loanAmount {
		return fmt.Errorf("insufficient reserve liquidity")
	}
	tx.WriteBalance("__reserve_pool__", reserveBal-loanAmount)

	borrowerBal, _ := tx.ReadBalance(borrower)
	tx.WriteBalance(borrower, borrowerBal+loanAmount)

	// Execute borrower's operations
	if err := operations(tx); err != nil {
		return fmt.Errorf("flash loan operations failed: %w", err)
	}

	// Verify repayment: borrower's final balance must show loan was repaid
	finalBorrowerBal, _ := tx.ReadBalance(borrower)
	if finalBorrowerBal < borrowerBal {
		return fmt.Errorf("flash loan not repaid: expected >= %d, got %d", borrowerBal, finalBorrowerBal)
	}

	// Verify reserve pool is whole
	finalReserve, _ := tx.ReadBalance("__reserve_pool__")
	if finalReserve < reserveBal {
		return fmt.Errorf("reserve pool not replenished")
	}

	return tx.Commit()
}
